const allowed = new Set(["seleciona_tratamento","analise_imagem_exame","exames","analise_imagem_consultas","consultas","transferencia_enfermeira","outras_situacoes","contratos","personalize_saude","agradecimento_no_final","programas_azul","programa_vermelho","pong","cancelamento_conexa","triagem_inicial_novo","debug_tool_post"]);
const raw = String($raw_scenario || '').trim();
const cleaned = raw.replace(/^```(?:json)?/i, '').replace(/```$/i, '').trim();
let selected = cleaned;
try {
  const parsed = JSON.parse(cleaned);
  selected = String(parsed.output || parsed.scenario || parsed.selected_scenario || '').trim();
} catch (error) {}
selected = selected.replace(/^['"]|['"]$/g, '').trim();
if (!allowed.has(selected)) selected = 'triagem_inicial_novo';
return selected;

